#!/usr/bin/env bash
# cAE and ccAE (random init) on the CURRENT Xitsonga + French DUSTED lists, WavLM layer 21.
# Features + alignments were regenerated by run_all.sh on 2026-10-06 and are reused as-is.
#
#     bash experiments/ccae_runs/run_dusted_cae.sh     (GATE_MB=5500 by default, see gpu_gate)
# Trains the cAE and re-runs the random-init ccAE on Xitsonga + French DUSTED, then evaluates.
#
# Same stage()/done-marker/log conventions as run_all.sh (shared state/ and logs/ dirs).

set -uo pipefail
cd "$(dirname "$0")/.."
PY=${PY:-python}
STATE=experiments/ccae_runs/state
LOGS=experiments/ccae_runs/logs
mkdir -p "$STATE" "$LOGS"
LAYER=21

stage() {  # stage <name> <command...>
    local name=$1; shift
    if [[ -f $STATE/$name.done ]]; then echo "[skip] $name"; return 0; fi
    echo "$name" > $STATE/CURRENT
    echo "[$(date '+%F %T')] START $name" | tee -a $LOGS/pipeline.log
    echo "\$ $*" > $LOGS/$name.log
    if "$@" >> $LOGS/$name.log 2>&1; then
        touch $STATE/$name.done
        echo "[$(date '+%F %T')] DONE  $name" | tee -a $LOGS/pipeline.log
    else
        touch $STATE/$name.failed
        echo "[$(date '+%F %T')] FAIL  $name (see $LOGS/$name.log)" | tee -a $LOGS/pipeline.log
        rm -f $STATE/CURRENT
        exit 1
    fi
}

# ---------- 0) back up old-list cAE DUSTED + yesterday's ccAE DUSTED results (copy, never move) ----------
backup() {
    local B=experiments/ccae_runs/backup_before_2026-10-07
    mkdir -p $B
    for c in Xitsonga ZS17French; do
        for m in cAE_DUSTED ccAErandinit_DUSTED; do
            cp -a models/${c}_WavLM/${m}_layer_21.pt $B/${c}_${m}_layer_21.pt
        done
        for d in results/ap/${c}_WavLMDUSTED/Normalised/test.samediff_cAE \
                 results/ap/${c}_WavLMDUSTED/Normalised/test.samediff_ccAErandinit \
                 results/abx/${c}_WavLMDUSTED/Normalised/test.abx_cAE_layer21 \
                 results/abx/${c}_WavLMDUSTED/Normalised/test.abx_ccAErandinit_layer21; do
            [[ -e $d ]] && mkdir -p $B/$(dirname $d) && cp -a $d $B/$d
        done
    done
    find $B -type f | sort
}
stage backup_before_dusted_rerun backup

# ---------- GPU gate: the GPU may be shared with other users ----------
# Evaluation stages (WavLM pass for ABX ~2.5-3 GB at the ~30 s longest segments, plus the
# CUDA DTW/ABX scorers) only start once >= GATE_MB is free on two checks 60 s apart, so they
# never squeeze another user's job. Training (small MLP, ~1.2 GB) is not gated.
GATE_MB=${GATE_MB:-5500}
gpu_gate() {
    local ok=0
    while (( ok < 2 )); do
        local free; free=$(nvidia-smi --query-gpu=memory.free --format=csv,noheader,nounits | head -1)
        if (( free >= GATE_MB )); then ok=$((ok+1)); else ok=0; fi
        echo "[$(date '+%F %T')] free=${free} MiB (need ${GATE_MB}) ok=${ok}/2" >> $LOGS/gpu_gate.log
        (( ok < 2 )) && sleep 60
    done
}
gated() {  # gated <stage name> <command...>: wait for the gate, then run as a stage
    [[ -f $STATE/$1.done ]] && { echo "[skip] $1"; return 0; }
    echo "gpu_gate (before $1)" > $STATE/CURRENT
    gpu_gate
    stage "$@"
}

XI_ITEMS=data/Information/Buckeye_tsonga/abx_items/test.item
FR_ITEMS=data/Information/ZS17French/abx_items/test.item
XI=Xitsonga_WavLMDUSTED
FR=ZS17French_WavLMDUSTED

# ---------- 1) train all four models first (not gated) ----------
stage train_xitsonga_dusted_cAE   $PY training/train_cae.py --features wavlm --corpus xitsonga --pairs dusted
stage train_zs17french_dusted_cAE $PY training/train_cae.py --features wavlm --corpus french --pairs dusted
stage train_xitsonga_dusted_ccAErandinit_rerun   $PY training/train_ccae.py --corpus xitsonga --pairs dusted --init random --layer $LAYER
stage train_zs17french_dusted_ccAErandinit_rerun $PY training/train_ccae.py --corpus zs17french --pairs dusted --init random --layer $LAYER

# ---------- 2) evaluate (each stage gated on free GPU memory) ----------
for spec in "xitsonga $XI $XI_ITEMS" "zs17french $FR $FR_ITEMS"; do
    read c set_ items <<< "$spec"
    gated ap_${c}_dusted_cAE      $PY evaluation/evaluate_ap.py data/Features/$set_/Normalised/test.samediff_cAE/layer_$LAYER
    gated abxfeat_${c}_dusted_cAE $PY evaluation/extract_abx_phone_features.py $set_ --subset test --layer $LAYER
    gated abx_${c}_dusted_cAE     $PY evaluation/score_abx.py data/Features/$set_/Normalised/test.abx_cAE_layer$LAYER $items
    t=${c}_dusted_ccAErandinit_rerun
    gated ap_$t      $PY evaluation/evaluate_ap.py data/Features/$set_/Normalised/test.samediff_ccAErandinit/layer_$LAYER
    gated abxfeat_$t $PY evaluation/extract_abx_phone_features.py $set_ --subset test --ccae --randinit --layer $LAYER
    gated abx_$t     $PY evaluation/score_abx.py data/Features/$set_/Normalised/test.abx_ccAErandinit_layer$LAYER $items
done

rm -f $STATE/CURRENT
echo "[$(date '+%F %T')] DUSTED cAE RUN DONE" | tee -a $LOGS/pipeline.log
